Object.assign(translations.id, {
  "كل ما تحتاجونه لراحة أكبر أثناء إقامتكم.": "Semua yang Anda butuhkan untuk menginap lebih nyaman.", "خدمات الغسيل والكي بعناية واهتمام.": "Layanan cuci dan setrika dengan penuh perhatian.", "نحن هنا لجعل إقامتكم أكثر راحة، لا تترددوا في التواصل معنا لأي استفسار أو طلب، وسنسعد بمساعدتكم.": "Kami hadir untuk membuat masa inap Anda lebih nyaman. Hubungi kami jika ada pertanyaan atau permintaan.", "يمكنكم التواصل مع فريق الفندق للحصول على المساعدة والإجابة عن جميع استفساراتكم.": "Hubungi tim hotel untuk mendapatkan bantuan dan jawaban atas pertanyaan Anda.", "يرجى تعبئة البيانات التالية وسنسعد بالتواصل معكم.": "Silakan isi informasi berikut dan kami akan menghubungi Anda.", "مشكلة أثناء الإقامة": "Masalah selama menginap", "ملاحظات واقتراحات": "Masukan dan saran", "راحتكم تهمنا": "Kenyamanan Anda penting bagi kami", "نسعى دائمًا لتقديم تجربة إقامة مميزة تلبي تطلعاتكم.": "Kami selalu berupaya memberikan pengalaman menginap yang istimewa.", "نهتم بأدق التفاصيل لنمنحكم إقامة أكثر راحة ورفاهية، مع مجموعة من الخدمات المصممة لتلبية احتياجاتكم بكل عناية.": "Kami memperhatikan setiap detail agar masa inap Anda lebih nyaman, dengan layanan yang dirancang untuk kebutuhan Anda.", "نعتني بملابسك ونحافظ على أناقتك من خلال خدمات الغسيل والكي بعناية.": "Kami merawat pakaian Anda dengan layanan cuci dan setrika yang teliti.", "تصفح الخدمات المتاحة، وحدد الكميات التي تحتاجها، وسيتم احتساب إجمالي طلبك تلقائيًا.": "Lihat layanan yang tersedia dan pilih jumlahnya. Total pesanan dihitung otomatis.", "لا تترددوا في التواصل معنا، فريقنا يسعد دائمًا بتقديم المساعدة لكم.": "Jangan ragu menghubungi kami. Tim kami siap membantu.", "ابقَ على اتصال طوال إقامتك من خلال شبكة الإنترنت الخاصة بالفندق.": "Tetap terhubung selama menginap dengan Wi-Fi hotel.", "تجربتكم تعني لنا الكثير، شاركونا آراءكم وملاحظاتكم لتطوير خدماتنا.": "Pengalaman Anda berarti bagi kami. Bagikan masukan untuk meningkatkan layanan.", "فريق الاستقبال متاح لمساعدتكم والإجابة عن استفساراتكم بكل اهتمام.": "Tim resepsionis siap membantu dan menjawab pertanyaan Anda.", "استمتعوا بتجربة مميزة، وتصفح قائمة المشروبات والمأكولات المتوفرة لدينا.": "Nikmati pengalaman istimewa dan lihat menu minuman serta makanan kami.", "اعتنِ بأناقتك مع خدمات الغسيل والكي، واختر الخدمة والكمية المناسبة لك.": "Rawat pakaian Anda dengan layanan laundry dan pilih layanan serta jumlah yang sesuai.", "إقامة مريحة وخدمات فندقية في مكان واحد.": "Penginapan nyaman dan layanan hotel dalam satu tempat."
});
