export function translateMessage(language: LanguageCode, message: string) {
  if (language === "ar") return message;
  const translated = translations[language][message];
  if (translated) return translated;
  console.error(`[i18n] Missing ${language} translation: ${message}`);
  return untranslatedLabel[language];
}

function localizeText(language: LanguageCode, source: string, dictionary: Record<string, string> | null) {
  if (language === "ar" || !dictionary) return source;
  let translated = dictionary[source] ?? source;
  if (translated === source) {
    for (const [arabic, localized] of Object.entries(dictionary).sort((a, b) => b[0].length - a[0].length)) {
      translated = translated.replaceAll(arabic, localized);
    }
  }
  if (/[\u0600-\u06ff]/.test(translated)) {
    console.error(`[i18n] Missing ${language} translation: ${source}`);
    translated = translated.replace(/[\u0600-\u06ff]+/g, untranslatedLabel[language]);
  }
  return translated;
}

function translatePage(language: LanguageCode) {
  const dictionary = language === "ar" ? null : translations[language];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let node: Node | null;
  while ((node = walker.nextNode())) {
    const text = node as Text;
    if (text.parentElement?.closest("[data-i18n-skip]")) continue;
    const lastLocalized = lastLocalizedText.get(text);
    const source = lastLocalized === undefined || text.data !== lastLocalized ? text.data : (originalText.get(text) ?? text.data);
    originalText.set(text, source);
    const key = source.replace(/\s+/g, " ").trim();
    if (language === "ar") {
      if (text.data !== source) text.data = source;
      lastLocalizedText.set(text, source);
    } else if (key && dictionary) {
      const translated = localizeText(language, key, dictionary);
      const parent = text.parentElement;
      if (parent?.tagName === "OPTION" && !parent.hasAttribute("value")) parent.setAttribute("value", key);
      if (text.data !== translated) text.data = translated;
      lastLocalizedText.set(text, translated);
    }
  }
  document.querySelectorAll("input, textarea, img, button").forEach((element) => {
    if (element.closest("[data-i18n-skip]")) return;
    ["placeholder", "alt", "aria-label", "title"].forEach((attribute) => {
      const value = element.getAttribute(attribute);
      if (value === null) return;
      const originals = originalAttributes.get(element) ?? new Map<string, string>();
      const localized = lastLocalizedAttributes.get(element) ?? new Map<string, string>();
      const previousValue = localized.get(attribute);
      const source = previousValue === undefined || value !== previousValue ? value : (originals.get(attribute) ?? value);
      originals.set(attribute, source);
      originalAttributes.set(element, originals);
      const translated = localizeText(language, source, dictionary);
      if (value !== translated) element.setAttribute(attribute, translated);
      localized.set(attribute, translated);
      lastLocalizedAttributes.set(element, localized);
    });
  });
}

