function getPageTitle(language: LanguageCode, pathname: string) {
  const normalizedPath = pathname === "/" ? "/" : pathname.replace(/\/$/, "");
  return pageTitles[language][normalizedPath] ?? pageTitles[language]["/"];
}

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const language = useSyncExternalStore<LanguageCode>(
    (listener) => {
      window.addEventListener("hotel-language-change", listener);
      window.addEventListener("storage", listener);
      return () => {
        window.removeEventListener("hotel-language-change", listener);
        window.removeEventListener("storage", listener);
      };
    },
    () => {
      const saved = window.localStorage.getItem("hotel-language") as LanguageCode | null;
      return languages.some((item) => item.code === saved) ? saved! : "ar";
    },
    () => "ar",
  );
  const setLanguage = (nextLanguage: LanguageCode) => {
    const selected = languages.find((item) => item.code === nextLanguage)!;
    document.documentElement.lang = selected.code;
    document.documentElement.dir = selected.dir;
    document.title = getPageTitle(nextLanguage, window.location.pathname);
    window.localStorage.setItem("hotel-language", selected.code);
    window.dispatchEvent(new Event("hotel-language-change"));
  };
  useEffect(() => {
    const selected = languages.find((item) => item.code === language)!;
    document.documentElement.lang = selected.code;
    document.documentElement.dir = selected.dir;
    const pageTitle = getPageTitle(language, pathname);
    const syncPageTitle = () => {
      const titleElements = document.head.querySelectorAll("title");
      const primaryTitle = titleElements[0] ?? document.createElement("title");
      if (!primaryTitle.isConnected) document.head.append(primaryTitle);
      titleElements.forEach((title, index) => {
        if (index > 0) title.remove();
      });
      if (primaryTitle.textContent !== pageTitle) primaryTitle.textContent = pageTitle;
    };
    syncPageTitle();
    const titleObserver = new MutationObserver(syncPageTitle);
    titleObserver.observe(document.head, { childList: true, characterData: true, subtree: true });
    const description = document.querySelector('meta[name="description"]');
    if (description) {
      const descriptions: Record<LanguageCode, string> = {
        ar: "إقامة مريحة وخدمات فندقية في مكان واحد.",
        en: "Comfortable stays and hotel services in one place.",
        id: "Penginapan nyaman dan layanan hotel dalam satu tempat.",
        tr: "Konforlu konaklama ve otel hizmetleri bir arada.",
        uz: "Qulay yashash va mehmonxona xizmatlari bir joyda.",
      };
      description.setAttribute("content", descriptions[language]);
    }
    window.localStorage.setItem("hotel-language", language);
    translatePage(language);
    return () => titleObserver.disconnect();
  }, [language, pathname]);

  useEffect(() => {
    const observer = new MutationObserver(() => translatePage(language));
    observer.observe(document.body, { childList: true, characterData: true, subtree: true });
    return () => observer.disconnect();
  }, [language]);
  return <LanguageContext.Provider value={{ language, setLanguage }}>{children}</LanguageContext.Provider>;
}

export function useLanguage() { return useContext(LanguageContext); }
